R.append((7432104,
("Pollo estilo pizza", "Una deliciosa cena de inspiración italiana que combina pechuga de pollo jugosa con el sabor de una pizza con queso. Esta receta fue seleccionada en colaboración con Slimming World.", "1", "398 g",
 ["½ cebolla morada pequeña, finamente picada", "½ pimiento rojo, sin semillas y picado", "1 diente de ajo pequeño, machacado", "Aceite en aerosol bajo en calorías", "2 tomates de rama, picados", "1 cucharada de tomate picado en lata", "1 cucharadita de puré de tomate", "1 cucharadita de orégano seco", "1 pechuga de pollo sin piel y sin hueso", "40 g de queso cheddar reducido en grasa, rallado", "1 tomate cherry, cortado por la mitad", "1 cucharadita de albahaca fresca finamente picada"],
 ["Ponga la cebolla, el pimiento y el ajo en una cacerola pequeña antiadherente. Rocíe con un par de disparos de aceite en aerosol bajo en calorías y cocine unos minutos hasta que se ablanden. Agregue los tomates frescos, el tomate en lata, el puré de tomate y el orégano, y cocine a fuego lento durante 5 minutos. Reserve.", "Precaliente el horno a 220 °C (200 °C con ventilador, marca de gas 7).", "Corte la pechuga de pollo por la mitad a lo largo, con cuidado de no cortarla por completo. Ábrala como si fuera una mariposa.", "Rocíe una sartén antiadherente con un par de disparos de aceite en aerosol bajo en calorías y colóquela a fuego medio. Agregue el pollo y cocine hasta que se dore por ambos lados. Pase el pollo a una bandeja antiadherente para hornear y hornee de 15 a 20 minutos, o hasta que esté bien cocido y no se vea carne rosada (los jugos deben salir claros al insertar una brocheta en la parte más gruesa del pollo).", "Saque el pollo del horno y extienda encima la mezcla de tomate. Espolvoree el queso y ponga encima el tomate cherry. Cocine 5 minutos más, hasta que el queso se derrita.", "Espolvoree con la albahaca y sirva caliente con papas en gajos caseras horneadas con cáscara y una ensalada verde grande y crujiente."],
 [], []),
("دجاج بنكهة البيتزا", "عشاء شهي بوحي إيطالي يجمع بين صدر الدجاج الطري ونكهة البيتزا بالجبن. تم اختيار هذه الوصفة بالتعاون مع Slimming World.", "1", "398 غرام",
 ["½ بصلة حمراء صغيرة، مفرومة ناعمًا", "½ فلفل رومي أحمر، منزوع البذور ومقطع", "1 فص ثوم صغير، مهروس", "بخاخ طهي قليل السعرات", "2 حبة طماطم عنقودية، مقطعة", "1 ملعقة كبيرة طماطم معلبة مقطعة", "1 ملعقة صغيرة معجون طماطم", "1 ملعقة صغيرة أوريجانو مجفف", "1 صدر دجاج بدون جلد وبدون عظم", "40 غرام جبن شيدر قليل الدسم، مبشور", "1 حبة طماطم كرزية، مقطوعة إلى نصفين", "1 ملعقة صغيرة ريحان طازج مفروم ناعمًا"],
 ["ضع البصل والفلفل والثوم في قدر صغير غير لاصق. رشّ عليها بخاخ الطهي قليل السعرات بضغطتين تقريبًا واطهها لبضع دقائق حتى تلين. أضف الطماطم الطازجة والطماطم المعلبة ومعجون الطماطم والأوريجانو واتركها على نار هادئة لمدة 5 دقائق. ضعها جانبًا.", "سخّن الفرن مسبقًا إلى 220° مئوية (200° مئوية للفرن بمروحة، علامة الغاز 7).", "اشطر صدر الدجاج إلى نصفين بالعرض، مع الحرص على ألا تقطعه بالكامل. افتحه ليأخذ شكل الفراشة.", "رشّ مقلاة غير لاصقة ببخاخ الطهي قليل السعرات بضغطتين تقريبًا وضعها على نار متوسطة. أضف الدجاج واطهه حتى يحمرّ من الجهتين. انقل الدجاج إلى صينية خبز غير لاصقة واخبزه لمدة 15-20 دقيقة أو حتى ينضج تمامًا ولا يظهر لحم وردي (يجب أن يخرج العصير صافيًا عند غرس سيخ في أسمك جزء من الدجاج).", "أخرج الدجاج من الفرن وافرد خليط الطماطم فوقه. رشّ الجبن وضع حبة الطماطم الكرزية في الأعلى. اطهه لمدة 5 دقائق أخرى حتى يذوب الجبن.", "رشّ الريحان وقدّمه ساخنًا مع أصابع البطاطس المنزلية المخبوزة في الفرن بقشرها، وطبق كبير من السلطة الخضراء المقرمشة."],
 [], [])))
